type Row = { value: string; expiresAt: number };

class SessionStore {
  private rows = new Map<string, Row>();

  set(t: number, key: string, value: string, ttl?: number): void {
    this.rows.set(key, { value, expiresAt: ttl === undefined ? Infinity : t + ttl });
  }
  private live(t: number, key: string): Row | null {
    const row = this.rows.get(key);
    if (!row) return null;
    if (t >= row.expiresAt) {
      this.rows.delete(key);
      return null;
    }
    return row;
  }
  get(t: number, key: string): string | null {
    return this.live(t, key)?.value ?? null;
  }
  delete(t: number, key: string): boolean {
    const had = this.live(t, key) !== null;
    this.rows.delete(key);
    return had;
  }
  scan(t: number, prefix: string): string[] {
    return [...this.rows.keys()]
      .filter((k) => k.startsWith(prefix))
      .sort()
      .filter((k) => this.live(t, k) !== null)
      .map((k) => `${k}=${this.rows.get(k)!.value}`);
  }
}

// The tests replay operations: ["set", t, key, value, ttl?], ["get", t, key], ["delete", t, key], ["scan", t, prefix].
// Every get, delete, and scan result is collected in order.
type Op = [string, number, string, string?, number?];
function simulate(ops: Op[]): (string | string[] | boolean | null)[] {
  const store = new SessionStore();
  const out: (string | string[] | boolean | null)[] = [];
  for (const [op, t, key, value, ttl] of ops) {
    if (op === "set") store.set(t, key, value!, ttl);
    else if (op === "get") out.push(store.get(t, key));
    else if (op === "delete") out.push(store.delete(t, key));
    else out.push(store.scan(t, key));
  }
  return out;
}
